@import url('https://fonts.googleapis.com/css2?family=Grenze:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Stranger Things — upside-down night, neon red serif title glow */
.theme-stranger-things {
  --bg: oklch(0.137 0.011 284.8);
  --surface: oklch(0.177 0.016 284.6);
  --surface-2: oklch(0.215 0.023 284.3);
  --fg: oklch(0.924 0.009 314.8);
  --fg-muted: oklch(0.637 0.038 296.3);
  --accent: oklch(0.603 0.235 27.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.638 0.129 259.7);
  --line: oklch(0.5 0.2 25 / 35%);
  --success: oklch(0.638 0.129 259.7);
  --warning: oklch(0.767 0.141 81.6);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.125rem;
  --radius-sm: 0px;
  --radius-lg: 0.25rem;
  --radius-pill: 0.25rem;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 20px color-mix(in oklab, var(--accent) 60%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Grenze", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.1em;
  --label-transform: uppercase;
  --label-tracking: 0.3em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-stranger-things h1,
.theme-stranger-things h2,
.theme-stranger-things h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-stranger-things { background-image: radial-gradient(ellipse at 50% 120%, oklch(0.35 0.16 25 / 30%), transparent 60%); }
.theme-stranger-things h1, .theme-stranger-things h2 { text-transform: uppercase; color: var(--accent); text-shadow: 0 0 14px color-mix(in oklab, var(--accent) 70%, transparent), 0 0 40px color-mix(in oklab, var(--accent) 40%, transparent); }
.theme-stranger-things h1 { -webkit-text-stroke: 1.5px oklch(0.68 0.24 27); color: transparent; }
.theme-stranger-things button { text-transform: uppercase; letter-spacing: 0.16em; }

/* alt-mode — Hawkins daylight: 80s cream, wallpaper + christmas-light dots */
.theme-stranger-things.alt-mode {
  --bg: oklch(0.955 0.018 85.0);
  --surface: oklch(0.978 0.012 85.0);
  --surface-2: oklch(0.925 0.022 83.0);
  --fg: oklch(0.245 0.030 280.0);
  --fg-muted: oklch(0.480 0.030 285.0);
  --accent: oklch(0.540 0.220 27.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.520 0.140 259.7);
  --line: oklch(0.540 0.160 27.0 / 30%);
  --success: oklch(0.520 0.130 155.0);
  --warning: oklch(0.640 0.140 75.0);
  --danger: oklch(0.520 0.210 27.0);
  --shadow-1: 0 1px 3px oklch(0.3 0.05 60 / 15%);
  --shadow-2: 0 6px 18px oklch(0.3 0.05 60 / 18%);
  --shadow-3: 0 18px 44px oklch(0.3 0.05 60 / 22%);
  --glow: 0 0 14px color-mix(in oklab, var(--accent) 30%, transparent);
  background-image:
    radial-gradient(circle 3px at 12% 8%, oklch(0.65 0.22 27 / 45%) 0 3px, transparent 3px),
    radial-gradient(circle 3px at 34% 5%, oklch(0.72 0.16 110 / 45%) 0 3px, transparent 3px),
    radial-gradient(circle 3px at 58% 9%, oklch(0.65 0.14 260 / 45%) 0 3px, transparent 3px),
    radial-gradient(circle 3px at 80% 6%, oklch(0.78 0.15 85 / 50%) 0 3px, transparent 3px),
    repeating-linear-gradient(90deg, oklch(0.60 0.10 60 / 4%) 0 2px, transparent 2px 56px);
}
.theme-stranger-things.alt-mode h1 { -webkit-text-stroke: 0px transparent; color: var(--accent); text-shadow: 1px 1px 0 oklch(0.85 0.06 60), 0 0 18px color-mix(in oklab, var(--accent) 25%, transparent); }
.theme-stranger-things.alt-mode h2 { color: var(--accent); text-shadow: none; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
